// Live Activity for events you joined (iOS 16.2+): Lock Screen and Dynamic
// Island show the event, the meeting point and a countdown to the start.
// Tapping it opens the event, where check-in is one tap.
// Uses expo-live-activity (the widget extension is generated by its config plugin).
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as LiveActivity from 'expo-live-activity';
import { Platform } from 'react-native';
import { lightPalette } from './theme';
import type { EventItem } from './types';

const KEY = 'qadam.liveActivities';
const WINDOW_BEFORE = 8 * 3600_000; // start showing 8 hours before the event

type Map = Record<string, string>; // event id → activity id

async function read(): Promise<Map> {
  try { return JSON.parse((await AsyncStorage.getItem(KEY)) ?? '{}') as Map; } catch { return {}; }
}
async function write(m: Map) {
  await AsyncStorage.setItem(KEY, JSON.stringify(m)).catch(() => {});
}

const config: LiveActivity.LiveActivityConfig = {
  backgroundColor: lightPalette.blue,
  titleColor: '#FFFFFF',
  subtitleColor: lightPalette.blueMist,
  progressViewTint: lightPalette.gold,
  progressViewLabelColor: '#FFFFFF',
  timerType: 'digital',
  imagePosition: 'left',
  imageSize: { width: 40, height: 40 },
};

function state(e: EventItem, subtitle: string): LiveActivity.LiveActivityState {
  return {
    title: e.title,
    subtitle,
    progressBar: { date: new Date(e.starts_at).getTime() },
    imageName: 'mark',
    dynamicIslandImageName: 'mark_small',
  };
}

/**
 * Keep Live Activities in step with the events I'm going to: start one when an
 * event is less than 8 hours away, end it once the event is over or I left.
 */
export async function syncEventActivities(events: EventItem[], meet: (place: string) => string) {
  if (Platform.OS !== 'ios') return;
  try {
    const now = Date.now();
    const map = await read();
    for (const e of events) {
      const start = new Date(e.starts_at).getTime();
      const end = start + e.duration_min * 60_000;
      const relevant = e.i_am_going && !e.cancelled && !e.i_checked_in && start - now < WINDOW_BEFORE && now < end;
      const id = map[e.id];
      if (relevant && !id) {
        const created = LiveActivity.startActivity(state(e, meet(e.meeting_point)),
          { ...config, deepLinkUrl: `/event/${e.id}` }, 0.8);
        if (created) map[e.id] = created;
      } else if (!relevant && id) {
        LiveActivity.stopActivity(id, state(e, meet(e.meeting_point)));
        delete map[e.id];
      }
    }
    await write(map);
  } catch (err) {
    console.warn('live activity skipped', err);
  }
}

/** End the activity for one event (after check-in or leaving). */
export async function endEventActivity(e: EventItem, finalLine: string) {
  if (Platform.OS !== 'ios') return;
  try {
    const map = await read();
    const id = map[e.id];
    if (!id) return;
    LiveActivity.stopActivity(id, { ...state(e, finalLine), progressBar: { progress: 1 } });
    delete map[e.id];
    await write(map);
  } catch {
    // decoration; ignore
  }
}
